test("EPIC041 Google validation probes are fixed, bounded, and discard provider data", async () => { let events = 0, busy = 0; const requests: Array<{ url: string; init: RequestInit | undefined }> = []; const transport = new GoogleCalendarValidationHttpTransport(async (url, init) => { requests.push({ url: String(url), init }); return new Response(String(url).includes("freeBusy") ? JSON.stringify({ calendars: { primary: { busy: [{ start: "secret-busy", end: "secret-busy" }] } } }) : JSON.stringify({ items: [{ id: "secret-event", summary: "secret-title", attendees: [{ email: "secret@example.test" }] }] }), { status: 200 }); }); await transport.getEvents({ accessToken: "token", signal: new AbortController().signal }); await transport.postFreeBusy({ accessToken: "token", body: "{}", signal: new AbortController().signal }); assert.equal(requests[0]?.url, "https://www.googleapis.com/calendar/v3/calendars/primary/events?maxResults=1"); assert.equal(requests[0]?.init?.method, "GET"); assert.equal(requests[0]?.init?.redirect, "error"); assert.equal(requests[1]?.url, "https://www.googleapis.com/calendar/v3/freeBusy"); assert.equal(requests[1]?.init?.method, "POST"); const provider = new GoogleCalendarValidationProvider({ acquire: async material => { assert.deepEqual(material, { version: "v1", opaqueSecret: "refresh-secret" }); return { kind: "success", accessToken: "token" }; } }, { getEvents: async () => { events++; return { status: 200, body: JSON.stringify({ items: [{ summary: "secret-title" }] }) }; }, postFreeBusy: async input => { busy++; assert.deepEqual(JSON.parse(input.body), { timeMin: at, timeMax: "2026-08-21T00:05:00.000Z", timeZone: "UTC", items: [{ id: "primary" }] }); return { status: 200, body: JSON.stringify({ calendars: { primary: { busy: [{ start: "secret-busy", end: "secret-busy" }] } } }) }; } }, { now: () => at }); const result = await provider.validate({ workspaceId: 1, companyId: 1, connectionId: "inc_00000000000000000000000000000000" as never, provider: "google_calendar", kind: "calendar", configuration: {}, plaintextSecret: JSON.stringify({ version: "v1", opaqueSecret: "refresh-secret" }) }); assert.deepEqual(result, { status: "valid" }); assert.equal(events, 1); assert.equal(busy, 1); assert.doesNotMatch(JSON.stringify(result), /secret|token|busy|event/i); const failed = new GoogleCalendarValidationProvider({ acquire: async () => ({ kind: "unauthorized" as const }) }, { getEvents: async () => { throw new Error("must not run"); }, postFreeBusy: async () => { throw new Error("must not run"); } }, { now: () => at }); assert.deepEqual(await failed.validate({ workspaceId: 1, companyId: 1, connectionId: "inc_00000000000000000000000000000000" as never, provider: "google_calendar", kind: "calendar", configuration: {}, plaintextSecret: JSON.stringify({ version: "v1", opaqueSecret: "refresh-secret" }) }), { status: "invalid", failureCode: "credentials_invalid" }); });

test("EPIC041 Google validation transport rejects chunked oversized responses", async () => { let reads = 0; const stream = new ReadableStream<Uint8Array>({ pull(controller) { reads++; controller.enqueue(new TextEncoder().encode("12345")); if (reads === 2) controller.close(); } }); const transport = new GoogleCalendarValidationHttpTransport(async () => new Response(stream, { status: 200 }), 8_000, 8); await assert.rejects(transport.getEvents({ accessToken: "token", signal: new AbortController().signal })); assert.equal(reads, 2); });
function setup() {
  const database = createDatabase(":memory:"), workspaces = new WorkspaceRepository(database), context = createWorkspaceContext(workspaces.resolveDefault()), other = createWorkspaceContext(workspaces.createForSystemUse({ key: "epic041-other", name: "EPIC041 Other" })), companies = new CompanyRepository(database), company = companies.create(context, { name: "EPIC041", website: "https://epic041.test" }), foreign = companies.create(other, { name: "EPIC041 Foreign", website: "https://epic041-foreign.test" });
  seed(database, context.workspaceId, company.id, "a"); seed(database, other.workspaceId, foreign.id, "b");
  return { database, context, other, company, foreign };
}
function ids(suffix: "a" | "b") { return { resource: `src_${suffix.repeat(32)}`, service: `ssv_${suffix.repeat(32)}`, hold: `shd_${suffix.repeat(32)}`, booking: `sbk_${suffix.repeat(32)}`, connection: `inc_${suffix.repeat(32)}` }; }
function seed(database: ReturnType<typeof createDatabase>, workspaceId: number, companyId: number, suffix: "a" | "b"): void {
  const value = ids(suffix);
  database.prepare("INSERT INTO scheduling_resources(id,workspace_id,company_id,location_id,name,normalized_name,timezone,capacity,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)").run(value.resource, workspaceId, companyId, null, `Resource ${suffix}`, `resource ${suffix}`, "UTC", 1, 1, at, at);
  database.prepare("INSERT INTO scheduling_services(id,workspace_id,company_id,resource_id,name,normalized_name,duration_minutes,buffer_before_minutes,buffer_after_minutes,slot_granularity_minutes,minimum_lead_minutes,maximum_horizon_days,active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").run(value.service, workspaceId, companyId, value.resource, `Service ${suffix}`, `service ${suffix}`, 30, 0, 0, 15, 0, 30, 1, at, at);
  database.prepare("INSERT INTO scheduling_holds(id,workspace_id,company_id,service_id,idempotency_key,start_at,end_at,occupied_start_at,occupied_end_at,expires_at,state,created_at,released_at) VALUES(?,?,?,?,?,?,?,?,?,?,?, ?,NULL)").run(value.hold, workspaceId, companyId, value.service, `hold-${suffix}`, "2026-08-21T01:00:00.000Z", "2026-08-21T01:30:00.000Z", "2026-08-21T01:00:00.000Z", "2026-08-21T01:30:00.000Z", "2026-08-21T02:00:00.000Z", "active", at);
  database.prepare("INSERT INTO scheduling_bookings(id,workspace_id,company_id,service_id,hold_id,reference,start_at,end_at,occupied_start_at,occupied_end_at,state,created_at,cancelled_at) VALUES(?,?,?,?,?,?,?,?,?,?,?, ?,NULL)").run(value.booking, workspaceId, companyId, value.service, null, `BK-${suffix}`, "2026-08-21T03:00:00.000Z", "2026-08-21T03:30:00.000Z", "2026-08-21T03:00:00.000Z", "2026-08-21T03:30:00.000Z", "confirmed", at);
  database.prepare("INSERT INTO integration_connections(id,workspace_id,company_id,provider,kind,configuration_json,status,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?)").run(value.connection, workspaceId, companyId, "calendar_test", "calendar", "{}", "inactive", 1, at, at);
}
function binding(id = "ecb_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa") { return { id, resourceId: ids("a").resource, connectionId: ids("a").connection, calendar: "calendar-a" }; }
function ready(database: ReturnType<typeof createDatabase>, workspaceId: number, companyId: number, connectionId: string, secret = JSON.stringify({ version: "v1", opaqueSecret: "opaque" })): void { database.prepare("UPDATE integration_connections SET status='active' WHERE id=? AND workspace_id=? AND company_id=?").run(connectionId, workspaceId, companyId); database.prepare("INSERT INTO integration_connection_operational_states(integration_connection_id,validation_state,validated_at,validation_failure_code,health_state,health_failure_code,last_provider_activity_at,updated_at) VALUES(?,?,?,NULL,?,NULL,?,?)").run(connectionId, "valid", at, "healthy", at, at); database.prepare("INSERT INTO integration_connection_secrets(integration_connection_id,encrypted_secret,created_at,updated_at) VALUES(?,?,?,?)").run(connectionId, `enc:${secret}`, at, at); }
function operation(overrides: Record<string, unknown> = {}): ExternalWriteOperation { const base = { id: "ewo_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", workspaceId: 1, companyId: 1, bindingId: "ecb_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", operation: "create" as const, idempotencyKey: "create-a", requestFingerprint: externalWriteRequestFingerprint({ operation: "create", bindingId: "ecb_aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", serviceId: ids("a").service, startAt: "2026-08-21T01:00:00.000Z", reference: "BK-a" }), state: "pending" as const, providerRequestCorrelationId: "operation-a", requestedBookingReference: "BK-a", bookingId: null, sourceBookingId: null, holdId: ids("a").hold, reservationExpiresAt: "2026-08-21T02:00:00.000Z", externalEventId: "event-a", expectedRemoteVersion: null, leaseToken: null, leaseOwner: null, leaseAcquiredAt: null, leaseExpiresAt: null, attemptCount: 0, lastAttemptAt: null, safeFailureCode: null, completedAt: null, createdAt: at, updatedAt: at }; return { ...base, ...overrides } as ExternalWriteOperation; }

