test("EPIC041 Google OAuth refresh uses the fixed endpoint and safe typed outcomes", async () => { const module = await import("../integrations/providers/googleCalendarAccessTokenProvider.js"), material = { version: "v1" as const, opaqueSecret: "refresh-secret" }; let status = 200, body = JSON.stringify({ access_token: "access-token" }), seen: RequestInit | undefined; const provider = new module.GoogleCalendarAccessTokenProvider("client-id", "client-secret", async (url, init) => { assert.equal(url, "https://oauth2.googleapis.com/token"); seen = init; return new Response(body, { status }); }); assert.deepEqual(await provider.acquire(material, new AbortController().signal), { kind: "success", accessToken: "access-token" }); assert.equal(seen?.method, "POST"); assert.equal(seen?.redirect, "error"); const form = new URLSearchParams(String(seen?.body)); assert.deepEqual(Object.fromEntries(form), { grant_type: "refresh_token", client_id: "client-id", client_secret: "client-secret", refresh_token: "refresh-secret" }); for (const [nextStatus, nextBody, expected] of [[400, JSON.stringify({ error: "invalid_grant" }), "unauthorized"], [401, "{}", "unauthorized"], [429, "{}", "rate_limited"], [503, "{}", "unavailable"], [200, "not-json", "invalid_response"], [200, "{}", "invalid_response"]] as const) { status = nextStatus; body = nextBody; assert.deepEqual(await provider.acquire(material, new AbortController().signal), { kind: expected }); } assert.equal(module.googleCalendarAccessTokenProviderFromEnvironment(undefined, undefined), null); assert.throws(() => module.googleCalendarAccessTokenProviderFromEnvironment("client-id", undefined), error => error instanceof module.GoogleCalendarOAuthConfigurationError && !error.message.includes("client-id")); const timeout = new module.GoogleCalendarAccessTokenProvider("client-id", "client-secret", async () => { throw new DOMException("Aborted", "AbortError"); }); assert.deepEqual(await timeout.acquire(material, new AbortController().signal), { kind: "timeout" }); });

const compositionProbe = `
  import * as graph from "./src/composition.ts";
  const registry = graph.providerAdapterRegistry;
  const validation = registry.resolveValidation("google_calendar", "calendar");
  const busy = registry.resolveCalendarBusy("google_calendar", "calendar");
  const events = registry.resolveCalendarEvents("google_calendar", "calendar");
  let duplicateRejected = false;
  if (validation && busy && events) {
    try { registry.register({ provider: "google_calendar", kind: "calendar", validation, calendarBusy: busy, calendarEvents: events }); }
    catch { duplicateRejected = true; }
  }
  const service = graph.integrationConnectionService;
  const refresh = graph.externalBusyRefreshService;
  const create = graph.externalBookingCreateService;
  const reschedule = graph.externalBookingRescheduleService;
  const cancel = graph.externalBookingCancelService;
  const router = graph.schedulingBookingRouter;
  const runtime = graph.operationalConversationTurnService.runtime;
  const tools = runtime.tools?.registry.list().map((tool) => tool.name) ?? [];
  console.log(JSON.stringify({
    registrations: registry.values.size,
    capabilities: { validation: !!validation, busy: !!busy, events: !!events },
    duplicateRejected,
    unknownClosed: registry.resolveValidation("unknown", "calendar") === null
      && registry.resolveValidation("google_calendar", "unknown") === null
      && registry.resolveCalendarBusy("google_calendar", "unknown") === null
      && registry.resolveCalendarEvents("unknown", "calendar") === null,
    shared: {
      validatorRegistry: service?.validator.registry === registry,
      busyRegistry: refresh.registry === registry,
      createRegistry: create.registry === registry,
      rescheduleRegistry: reschedule.registry === registry,
      cancelRegistry: cancel.registry === registry,
      busyCredentials: busy?.credentials === events?.credentials,
      validationTokenProvider: validation?.tokens === busy?.tokens && validation?.tokens === events?.tokens,
      validationDoesNotUseScopedCredentials: validation?.credentials === undefined,
      bindingShared: refresh.bindings === create.bindings && refresh.bindings === reschedule.bindings && refresh.bindings === cancel.bindings,
      bindingRepositories: refresh.bindings.bindings.constructor.name === "ExternalCalendarRepository"
        && refresh.bindings.connections === service?.repository,
      routerAuthorities: router.bindings === refresh.bindings
        && router.externalCreate === create
        && router.externalReschedule === reschedule
        && router.externalCancel === cancel
        && router.mappings === create.operations
        && router.scheduling === create.schedulingRepository,
    },
    services: {
      integration: !!service,
      binding: refresh.bindings.constructor.name === "ExternalCalendarBindingService",
      busyRefresh: refresh.constructor.name === "ExternalBusyRefreshService",
      create: create.constructor.name === "ExternalBookingCreateService",
      reschedule: reschedule.constructor.name === "ExternalBookingRescheduleService",
      cancel: cancel.constructor.name === "ExternalBookingCancelService",
      router: router.constructor.name === "SchedulingBookingRouter",
      automaticBusyTrigger: "timer" in refresh || "interval" in refresh || "scheduler" in refresh,
    },
    assistant: { tools, runtime: runtime.constructor.name },
  }));
`;

function probeComposition(environment: Record<string, string | undefined> = {}): { readonly status: number | null; readonly output: string; readonly graph: Record<string, unknown> | null } {
  const env = { ...process.env, NODE_ENV: "development" } as NodeJS.ProcessEnv;
  for (const key of ["ATLAS_INTEGRATION_SECRET_KEY", "GOOGLE_CALENDAR_OAUTH_CLIENT_ID", "GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET", "WHATSAPP_PLATFORM_ENCRYPTION_KEY", "WHATSAPP_ACCESS_TOKEN"]) delete env[key];
  Object.assign(env, environment);
  const result = spawnSync(process.execPath, ["node_modules/tsx/dist/cli.mjs", "--eval", compositionProbe], { cwd: resolve(process.cwd()), env, encoding: "utf8" });
  const output = `${result.stdout}\n${result.stderr}`;
  const line = result.stdout.trim().split("\n").filter(Boolean).at(-1);
  return { status: result.status, output, graph: result.status === 0 && line ? JSON.parse(line) as Record<string, unknown> : null };
}

test("EPIC041 production composition owns one registry and wires all Google capabilities to shared authorities", () => {
  const result = probeComposition({ ATLAS_INTEGRATION_SECRET_KEY: "a".repeat(64), GOOGLE_CALENDAR_OAUTH_CLIENT_ID: "test-google-client", GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET: "test-google-client-secret" });
  assert.equal(result.status, 0, result.output);
  const graph = result.graph!;
  assert.equal(graph.registrations, 1);
  assert.deepEqual(graph.capabilities, { validation: true, busy: true, events: true });
  assert.equal(graph.duplicateRejected, true);
  assert.equal(graph.unknownClosed, true);
  assert.deepEqual(graph.shared, { validatorRegistry: true, busyRegistry: true, createRegistry: true, rescheduleRegistry: true, cancelRegistry: true, busyCredentials: true, validationTokenProvider: true, validationDoesNotUseScopedCredentials: true, bindingShared: true, bindingRepositories: true, routerAuthorities: true });
  assert.deepEqual(graph.services, { integration: true, binding: true, busyRefresh: true, create: true, reschedule: true, cancel: true, router: true, automaticBusyTrigger: false });
  assert.equal((graph.assistant as { runtime: string }).runtime, "OperationalAssistantRuntime");
  assert.deepEqual((graph.assistant as { tools: string[] }).tools.sort(), ["live_data.read", "scheduling.cancel_booking", "scheduling.create_booking", "scheduling.get_booking", "scheduling.reschedule_booking"]);
});

test("EPIC041 production composition gates Google configuration safely without WhatsApp fallback", () => {
  const cipherOnly = probeComposition({ ATLAS_INTEGRATION_SECRET_KEY: "b".repeat(64) });
  assert.equal(cipherOnly.status, 0, cipherOnly.output);
  assert.equal(cipherOnly.graph?.registrations, 0);
  assert.equal((cipherOnly.graph?.services as { integration: boolean }).integration, true);
  const absent = probeComposition();
  assert.equal(absent.status, 0, absent.output);
  assert.equal(absent.graph?.registrations, 0);
  assert.equal((absent.graph?.services as { integration: boolean }).integration, false);
  const oauthWithoutCipher = probeComposition({ GOOGLE_CALENDAR_OAUTH_CLIENT_ID: "test-google-client", GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET: "test-google-client-secret", WHATSAPP_PLATFORM_ENCRYPTION_KEY: "c".repeat(64) });
  assert.equal(oauthWithoutCipher.status, 0, oauthWithoutCipher.output);
  assert.equal(oauthWithoutCipher.graph?.registrations, 0);
  const partial = probeComposition({ ATLAS_INTEGRATION_SECRET_KEY: "a".repeat(64), GOOGLE_CALENDAR_OAUTH_CLIENT_ID: "test-google-client", GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET: undefined, WHATSAPP_ACCESS_TOKEN: "test-whatsapp-secret" });
  assert.notEqual(partial.status, 0);
  assert.match(partial.output, /GOOGLE_CALENDAR_OAUTH_CLIENT_ID and GOOGLE_CALENDAR_OAUTH_CLIENT_SECRET/);
  for (const secret of ["a".repeat(64), "test-google-client", "test-google-client-secret", "test-whatsapp-secret", "refresh-token", "access-token", "Authorization"]) assert.doesNotMatch(partial.output, new RegExp(secret, "i"));
});

test("EPIC041 registered validation drives readiness and rotation without exposing provider secrets", async () => {
  const value = setup();
  try {
    const seen: string[] = [];
    const registry = new ProviderAdapterRegistry();
    registry.register({ provider: "google_calendar", kind: "calendar", validation: { validate: async input => { seen.push(input.plaintextSecret); return { status: "valid" }; } } });
    const service = new IntegrationConnectionService(new IntegrationConnectionRepository(new LocalSqlDatabase(value.database)), { encrypt: secret => `safe:${secret}`, decrypt: secret => secret.slice(5) }, new RegistryIntegrationProviderValidator(registry), { now: () => at });
    const connection = await service.create(value.context, value.company.id, { provider: "google_calendar", kind: "calendar" });
    const configured = await service.configureSecret(value.context, value.company.id, connection.id, "refresh-one");
    const validated = await service.validate(value.context, value.company.id, configured.id);
    assert.equal(validated.status, "inactive");
    assert.equal((await new IntegrationConnectionRepository(new LocalSqlDatabase(value.database)).findState(value.context, value.company.id, connection.id))?.validationState, "valid");
    assert.equal((await service.activate(value.context, value.company.id, validated.id)).status, "active");
    const rotated = await service.configureSecret(value.context, value.company.id, connection.id, "refresh-two");
    assert.equal(rotated.status, "inactive");
    assert.equal((await new IntegrationConnectionRepository(new LocalSqlDatabase(value.database)).findState(value.context, value.company.id, connection.id))?.validationState, "not_validated");
    await service.validate(value.context, value.company.id, connection.id);
    assert.deepEqual(seen, ["refresh-one", "refresh-two"]);
    const unknown = await service.create(value.context, value.company.id, { provider: "unknown_calendar", kind: "calendar" });
    await service.configureSecret(value.context, value.company.id, unknown.id, "refresh-three");
    const rejected = await service.validate(value.context, value.company.id, unknown.id);
    assert.equal(rejected.status, "inactive");
    assert.equal((await new IntegrationConnectionRepository(new LocalSqlDatabase(value.database)).findState(value.context, value.company.id, unknown.id))?.validationState, "invalid");
    assert.doesNotMatch(JSON.stringify({ rejected, seen: seen.map(() => "redacted") }), /refresh-one|refresh-two|refresh-three/);
  } finally { value.database.close(); }
});

test("EPIC041 production composition keeps external booking writes outside assistant runtime wiring", () => {
  const composition = readFileSync(resolve(process.cwd(), "src/composition.ts"), "utf8");
  const runtime = readFileSync(resolve(process.cwd(), "src/assistant/services/operationalAssistantRuntime.ts"), "utf8");
  const tools = readFileSync(resolve(process.cwd(), "src/scheduling/application/bookingToolDefinitions.ts"), "utf8");
  assert.match(composition, /schedulingBookingToolDefinitions\(bookingCommands,bookingQueries\)/);
  assert.doesNotMatch(composition, /schedulingBookingToolDefinitions\([^)]*externalBooking/);
  assert.doesNotMatch(runtime, /ExternalBooking(?:Create|Reschedule|Cancel)Service/);
  assert.doesNotMatch(tools, /ExternalBooking(?:Create|Reschedule|Cancel)Service/);
  assert.match(tools, /confirmationPolicy: "user"/);
  assert.match(tools, /idempotencyPolicy: "source_owned_required"/);
});
